// Des: Parse schedules once; each tick only checks due
// Flo: arm(task) > parse + validate sche > Armed union > due(now) each tick > fire verdict
// I/O: Task + local time (store, ticker) > Armed + due verdict, or ArmError (ticker)
// ===================================================================
const std = @import("std"); const stor = @import("taskstore"); const time = @import("tasktime"); const even = @import("taskevent"); const supe = @import("tasksuper"); const prob = @import("taskprobe");
const CF = .{ .secs = 1000, .trim = " \t", .boot = "boot", .nopa = "no arm path" };
pub const ArmError = error{ BadCron, BadPulse, BadOnce, BadSolar, NeedsSolarConfig, NotTimeType, NeedsPath, BadFlagPrefix, BadLink, BadChain, NeedsSpec, BadPort, BadHost, BadUrl, BadSize, BadDuration, BadProc, BadPowerSpec };
pub const Kind = union(enum) { cron: time.CronFields, pulse: u64, once: i64, solar: time.SolarSpec, fsctl: even.Stat, link: supe.LinkSpec, loop: void, probe: prob.Prob, chain: ChainSpec, unsupported: []const u8 };
pub const Trig = union(enum) { cron: time.CronFields, pulse: u64, solar: time.SolarSpec };
pub const ChainSpec = struct { trig: ?Trig, hand: bool = false };
pub const Armed = struct {
id: []const u8, kind: Kind, last_minute: i64 = -1, next_due_ms: i64 = 0, fired: bool = false, fire_count: u32 = 0, last_fire_ms: i64 = 0,
pub fn due(self: *Armed, iozz: std.Io, nowz: time.Local, nowz_msec: i64, sola: ?SolarConfig) bool { switch (self.kind) { .cron => |fiel| return self.trigDuez(.{ .cron = fiel }, nowz, nowz_msec, sola), .pulse => |msec| return self.trigDuez(.{ .pulse = msec }, nowz, nowz_msec, sola), .once => |targ| { if (self.fired) return false; if (!time.onceDue(targ, nowz)) return false; self.fired = true; return true; }, .solar => |spec| return self.trigDuez(.{ .solar = spec }, nowz, nowz_msec, sola), .fsctl => |*stat| return stat.duez(iozz, nowz_msec), .link => return false, .loop => return false, .probe => return false, .chain => |chai| return if (chai.trig) |trig| self.trigDuez(trig, nowz, nowz_msec, sola) else false, .unsupported => return false } }
fn trigDuez(self: *Armed, trig: Trig, nowz: time.Local, nowz_msec: i64, sola: ?SolarConfig) bool { switch (trig) { .cron => |fiel| { if (nowz.minute_stamp == self.last_minute) return false; self.last_minute = nowz.minute_stamp; return time.cronMatch(fiel, nowz); }, .pulse => |inte_msec| { if (self.next_due_ms == 0) { self.next_due_ms = nowz_msec + @as(i64, @intCast(inte_msec)); return false; } if (nowz_msec < self.next_due_ms) return false; self.next_due_ms = nowz_msec + @as(i64, @intCast(inte_msec)); return true; }, .solar => |spec| { const conf = sola orelse return false; if (nowz.minute_stamp == self.last_minute) return false; self.last_minute = nowz.minute_stamp; const targ = time.solarMinuteStamp(spec, unixFrom(nowz_msec), conf.lat, conf.lng) orelse return false; return nowz.minute_stamp == targ; } } }
pub fn isBoot(self: *const Armed) bool { return switch (self.kind) { .fsctl => |stat| stat.kind == .boot, else => false }; }
pub fn markBootFired(self: *Armed) void { switch (self.kind) { .fsctl => |*stat| if (stat.kind == .boot) { stat.boot_fire = true; }, else => {} } }
pub fn isChain(self: *const Armed) bool { return self.kind == .chain; }
pub fn chainBoots(self: *const Armed) bool { return switch (self.kind) { .chain => |chai| chai.trig == null, else => false }; }
pub fn takeChainHand(self: *Armed) bool { switch (self.kind) { .chain => |*chai| { const hand = chai.hand; chai.hand = false; return hand; }, else => return false } }
pub fn linkSpec(self: *const Armed) ?supe.LinkSpec { return switch (self.kind) { .link => |spec| spec, else => null }; }
pub fn isLoop(self: *const Armed) bool { return self.kind == .loop; }
pub fn requestHand(self: *Armed) bool { switch (self.kind) { .fsctl => |*stat| { if (stat.kind != .hand) return false; stat.hand_requ = true; return true; }, .chain => |*chai| { chai.hand = true; return true; }, else => return false } }
pub fn claimedFile(self: *const Armed) []const u8 { return switch (self.kind) { .fsctl => |stat| if (stat.kind == .queu) stat.clai() else "", else => "" }; }
pub fn markFired(self: *Armed, nowz_msec: i64) void { self.fire_count += 1; self.last_fire_ms = nowz_msec; }
pub fn nextFireStamp(self: *const Armed, nowz: time.Local) ?i64 { return switch (self.kind) { .cron => |fiel| time.nextCronMinute(fiel, nowz), .once => if (self.fired) null else self.kind.once, .pulse, .solar, .fsctl, .link, .loop, .probe, .chain, .unsupported => null }; }
pub fn typeName(self: *const Armed) []const u8 { return switch (self.kind) { .cron => "cron", .pulse => "puls", .once => "once", .solar => "sola", .fsctl => |stat| stat.typeName(), .link => "link", .loop => "loop", .probe => |item| item.typeName(), .chain => "chai", .unsupported => "unsupported" }; }
pub fn probeState(self: *const Armed) ?[]const u8 { return switch (self.kind) { .probe => |item| item.statName(), else => null }; }
pub fn probePtr(self: *Armed) ?*prob.Prob { return switch (self.kind) { .probe => |*item| item, else => null }; }
};
pub const SolarConfig = struct { lat: f64, lng: f64 };
fn unixFrom(nowz_msec: i64) i64 { return @divFloor(nowz_msec, CF.secs); }
fn chaiTrig(sche: []const u8) ?Trig { if (time.parseCron(sche)) |fiel| return .{ .cron = fiel } else |_| {} const unit = switch (sche[sche.len - 1]) { 's', 'S', 'm', 'M', 'h', 'H' => true, else => false }; if (unit) if (time.parsePulse(sche)) |msec| return .{ .pulse = msec } else |_| {}; if (time.parseSolar(sche)) |spec| return .{ .solar = spec } else |_| {} return null; }
pub fn armTask(task: stor.Task) ArmError!Armed { const sche = task.sche orelse ""; if (std.mem.eql(u8, task.type, "cron")) { const fiel = time.parseCron(sche) catch return ArmError.BadCron; return .{ .id = task.id, .kind = .{ .cron = fiel } }; } if (std.mem.eql(u8, task.type, "puls")) { const msec = time.parsePulse(sche) catch return ArmError.BadPulse; return .{ .id = task.id, .kind = .{ .pulse = msec } }; } if (std.mem.eql(u8, task.type, "once")) { const stam = time.parseOnce(sche) catch return ArmError.BadOnce; return .{ .id = task.id, .kind = .{ .once = stam } }; } if (std.mem.eql(u8, task.type, "sola")) { const spec = time.parseSolar(sche) catch return ArmError.BadSolar; return .{ .id = task.id, .kind = .{ .solar = spec } }; } if (std.mem.eql(u8, task.type, "link")) { const spec = supe.linkPars(sche) catch return ArmError.BadLink; return .{ .id = task.id, .kind = .{ .link = spec } }; } if (std.mem.eql(u8, task.type, "loop")) return .{ .id = task.id, .kind = .loop }; if (std.mem.eql(u8, task.type, "chai")) { const trim = std.mem.trim(u8, sche, CF.trim); if (trim.len == 0 or std.mem.eql(u8, trim, CF.boot)) return .{ .id = task.id, .kind = .{ .chain = .{ .trig = null } } }; const trig = chaiTrig(trim) orelse return ArmError.BadChain; return .{ .id = task.id, .kind = .{ .chain = .{ .trig = trig } } }; } if (even.typeEvenChec(task.type)) { const stat = even.statArmz(task.type, task.sche, task.dela) catch |erro| return switch (erro) { error.NeedsPath => ArmError.NeedsPath, error.BadFlagPrefix => ArmError.BadFlagPrefix, error.NotEventType => ArmError.NotTimeType }; return .{ .id = task.id, .kind = .{ .fsctl = stat } }; } if (prob.probTypeChec(task.type)) { const item = prob.probArmz(task.type, task.sche) catch |erro| return switch (erro) { error.NeedsSpec => ArmError.NeedsSpec, error.BadPort => ArmError.BadPort, error.BadHost => ArmError.BadHost, error.BadUrl => ArmError.BadUrl, error.BadSize => ArmError.BadSize, error.BadDuration => ArmError.BadDuration, error.BadProc => ArmError.BadProc, error.BadPowerSpec => ArmError.BadPowerSpec, error.NotProbeType => ArmError.NotTimeType }; return .{ .id = task.id, .kind = .{ .probe = item } }; } return .{ .id = task.id, .kind = .{ .unsupported = CF.nopa } }; }
// =======================___THIS_IS_THE_END___=======================
